import sys

def min_difference(N, weights):
    total_sum = sum(weights)
    half_sum = total_sum // 2
    dp = [float('inf')] * (half_sum + 1)
    dp[0] = 0

    for weight in weights:
        for j in range(half_sum, weight - 1, -1):
            dp[j] = min(dp[j], dp[j - weight])

    return abs(total_sum - 2 * dp[half_sum])

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    weights = list(map(int, data[1:]))
    print(min_difference(N, weights))
